package com.app.controller;
import com.app.security.UserPrincipal;import com.app.service.SocietyAttendanceImportService;import lombok.RequiredArgsConstructor;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.Map;
@RestController @RequestMapping("/society/attendance/imports") @RequiredArgsConstructor public class SocietyAttendanceImportController {private final SocietyAttendanceImportService service;@PostMapping(consumes="multipart/form-data") public Map<String,Integer> importAttendance(@AuthenticationPrincipal UserPrincipal p,@RequestParam String method,@RequestPart("file") MultipartFile file){return Map.of("imported",service.importCsv(p.getAccountId(),p.getUserId(),method,file));}}
